/**
 * Item entry form — captures all fields for a single consignment item and adds it to the
 * current intake session. Item code is auto-generated by the backend.
 *
 * Field order (2026-09-18): Qty · Category · Type · Brand · Description ·
 * Size · Sell Price · Donate. Gender/Age, Color, Year, and Used were
 * SUPPRESSED per request — the database columns remain (legacy items keep
 * their values; new items use the backend defaults, e.g. used=True).
 *
 * @module ItemForm
 */
import { useEffect, useRef, useState, type FormEvent } from "react";
import { addItem } from "../api/intakes";
import { capitalizeWords } from "../lib/format";
import { fetchBrands } from "../api/items";
import { CATEGORIES, typesForCategory } from "../lib/itemSizes";
import type { Item } from "../types";

import { BUTTON_STYLE } from "../lib/buttons";
import { ITEM_FORM, variantProps, v1Only, v2Only } from "./intakeStyles";
import { useUiVariant } from "../lib/uiVariant";

const emptyForm = (donateUnsold: boolean) => ({
  quantity: "1",
  category: "",
  type: "",
  brand: "",
  description: "",
  size: "",
  price: "",
  donate_unsold: donateUnsold,
});

/**
 * Form component for adding a single item to an intake session.
 * Validates required fields (category, price), submits via the intakes API,
 * and resets after each successful submission. Item code is auto-generated by the backend.
 *
 * @param props.intakeId - ID of the intake session to which the item will be added.
 * @param props.onAdded - Callback invoked with the newly created {@link Item} on success.
 */
export function ItemForm({
  intakeId,
  onAdded,
  defaultDonateUnsold = false,
}: {
  intakeId: number;
  onAdded: (item: Item) => void;
  /** Per-item donate-unsold initial state; inherits the intake's (and seller's) preference. */
  defaultDonateUnsold?: boolean;
}) {
  const [f, setF] = useState(() => emptyForm(defaultDonateUnsold));
  const [error, setError] = useState<string | null>(null);
  const [priceNote, setPriceNote] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [brandSuggestions, setBrandSuggestions] = useState<string[]>([]);
  const v2 = useUiVariant() === "v2";
  // Focus handle for the Quantity field (#6): focused on mount and again after
  // each successful add, so back-to-back entries start where the staff always
  // begin — the Qty box.
  const quantityRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    quantityRef.current?.focus();
  }, []);

  /** Brand typeahead: fetch matching existing brands (scoped to the selected
   *  category when one is chosen) as the cashier types. */
  async function handleBrandInput(value: string) {
    set("brand", value);
    if (value.trim().length < 1) {
      setBrandSuggestions([]);
      return;
    }
    try {
      setBrandSuggestions(
        await fetchBrands(value.trim(), f.category || undefined),
      );
    } catch {
      setBrandSuggestions([]);
    }
  }

  function set(k: keyof ReturnType<typeof emptyForm>, v: string | boolean) {
    setF((prev) => ({ ...prev, [k]: v }));
  }

  /** Category change clears Type (and Size) so the pair stays consistent. */
  function handleCategoryChange(newCategory: string) {
    setF((prev) => ({ ...prev, category: newCategory, type: "", size: "" }));
  }

  function handleTypeChange(newType: string) {
    setF((prev) => ({ ...prev, type: newType, size: "" }));
  }

  /** Whole-dollar price entry: show a live "rounds up" note when the user
   *  types cents (same ceiling rule as bulk import; never blocks typing). */
  function handlePriceInput(value: string) {
    set("price", value);
    setPriceNote(null);
    const v = parseFloat(value);
    if (Number.isFinite(v) && v > 0 && !Number.isInteger(v)) {
      setPriceNote(`Rounds up to $${Math.ceil(v)} (whole dollars only)`);
    }
  }

  async function handleSubmit(e: FormEvent) {
    e.preventDefault();
    setError(null);
    setLoading(true);
    // Whole-dollar pricing: round UP to the nearest dollar (same rule as bulk
    // intake import).
    const wholePrice = Math.ceil(parseFloat(f.price));
    try {
      // Suppressed fields (gender_age, color, year, used) are NOT sent — the
      // backend defaults apply (used=True for new intake items).
      const item = await addItem(intakeId, {
        category: f.category || undefined,
        brand: f.brand,
        type: f.type || undefined,
        description: f.description || undefined,
        size: f.size || undefined,
        price: wholePrice,
        quantity: Math.max(1, parseInt(f.quantity) || 1),
        donate_unsold: f.donate_unsold,
      });
      onAdded(item);
      setF(emptyForm(defaultDonateUnsold));
      setPriceNote(null);
      // Next item starts at the top (#6): refocus Qty after the reset.
      quantityRef.current?.focus();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to add item");
    } finally {
      setLoading(false);
    }
  }

  const descOver = f.description.length >= 90;

  return (
    <form onSubmit={handleSubmit}>
      <h4>Add Item</h4>
      <div {...variantProps(v2, "ui2-itemform-grid", ITEM_FORM.grid)}>
        <div {...variantProps(v2, "ui2-itemform-field", ITEM_FORM.field)}>
          <label htmlFor="quantity"
            {...variantProps(v2, "ui2-itemform-label", ITEM_FORM.label)}
          >
            Qty
          </label>
          <input
            id="quantity"
            ref={quantityRef}
            type="number"
            min="1"
            step="1"
            value={f.quantity}
            onChange={(e) => set("quantity", e.target.value)}
            {...variantProps(v2, "ui2-itemform-input", ITEM_FORM.inputBox)}
          />
        </div>
        <div {...variantProps(v2, "ui2-itemform-field", ITEM_FORM.field)}>
          <label htmlFor="category"
            {...variantProps(v2, "ui2-itemform-label", ITEM_FORM.label)}
          >
            Category *
          </label>
          <select
            id="category"
            value={f.category}
            onChange={(e) => handleCategoryChange(e.target.value)}
            required
            {...variantProps(v2, "ui2-itemform-input", ITEM_FORM.inputPlain)}
          >
            <option value="">— select —</option>
            {CATEGORIES.map((c) => (
              <option key={c} value={c}>
                {c}
              </option>
            ))}
          </select>
        </div>
        <div {...variantProps(v2, "ui2-itemform-field", ITEM_FORM.field)}>
          <label htmlFor="type"
            {...variantProps(v2, "ui2-itemform-label", ITEM_FORM.label)}
          >
            Type
          </label>
          <select
            id="type"
            value={f.type}
            onChange={(e) => handleTypeChange(e.target.value)}
            {...variantProps(v2, "ui2-itemform-input", ITEM_FORM.inputPlain)}
          >
            <option value="">— select type —</option>
            {typesForCategory(f.category).map((t) => (
              <option key={t} value={t}>
                {t}
              </option>
            ))}
          </select>
        </div>
        <div {...variantProps(v2, "ui2-itemform-field", ITEM_FORM.field)}>
          <label htmlFor="brand"
            {...variantProps(v2, "ui2-itemform-label", ITEM_FORM.label)}
          >
            Brand *
          </label>
          <input
            id="brand"
            list="brand-suggestions"
            value={f.brand}
            onChange={(e) => handleBrandInput(e.target.value)}
            required
            {...variantProps(v2, "ui2-itemform-input", ITEM_FORM.inputPlain)}
          />
          <datalist id="brand-suggestions">
            {brandSuggestions.map((b) => (
              <option key={b} value={b} />
            ))}
          </datalist>
        </div>
        <div {...variantProps(v2, "ui2-itemform-field", ITEM_FORM.field)}>
          <label htmlFor="description"
            {...variantProps(v2, "ui2-itemform-label", ITEM_FORM.label)}
          >
            Description
          </label>
          <input
            id="description"
            value={f.description}
            onChange={(e) => set("description", capitalizeWords(e.target.value))}
            maxLength={99}
            {...variantProps(v2, "ui2-itemform-input", ITEM_FORM.inputBox)}
          />
          <div
            {...variantProps(
              v2,
              descOver ? "ui2-itemform-counter ui2-itemform-counter--over" : "ui2-itemform-counter",
              ITEM_FORM.counter(descOver),
            )}
          >
            {f.description.length} / 99
          </div>
        </div>
        <div {...variantProps(v2, "ui2-itemform-field", ITEM_FORM.field)}>
          <label htmlFor="size"
            {...variantProps(v2, "ui2-itemform-label", ITEM_FORM.label)}
          >
            Size
          </label>
          {/* Size is free text: the size scale varies too much per item (cm
              lengths, Mondo boot sizes, US apparel sizes) for a fixed list to
              cover it, and intake staff type what is printed on the item. */}
          <input
            id="size"
            value={f.size}
            onChange={(e) => set("size", e.target.value)}
            placeholder="e.g. 170cm, 27.5, M"
            {...variantProps(v2, "ui2-itemform-input", ITEM_FORM.inputBox)}
          />
        </div>
        <div {...variantProps(v2, "ui2-itemform-field", ITEM_FORM.field)}>
          <label htmlFor="price"
            {...variantProps(v2, "ui2-itemform-label", ITEM_FORM.label)}
          >
            Sell Price * (whole dollars)
          </label>
          <input
            id="price"
            type="number"
            min="0"
            step="0.01"
            value={f.price}
            onChange={(e) => handlePriceInput(e.target.value)}
            required
            {...variantProps(v2, "ui2-itemform-input", ITEM_FORM.inputBox)}
          />
          {priceNote && (
            <div {...variantProps(v2, "ui2-itemform-price-note", ITEM_FORM.priceNote)}>
              {priceNote}
            </div>
          )}
        </div>
      </div>
      <div {...variantProps(v2, "ui2-itemform-donate", ITEM_FORM.donateRow)}>
        <div>
          <label>
            <input
              type="checkbox"
              checked={f.donate_unsold}
              onChange={(e) => set("donate_unsold", e.target.checked)}
            />{" "}
            Donate?
          </label>
          {/* Inheritance visibility (tester feedback: "inherit donation permission
              from seller registration onto equipment intake — not sure this is working").
              Show the inherited value the checkbox starts from. */}
          <div {...variantProps(v2, "ui2-itemform-inherit", ITEM_FORM.inheritNote)}>
            Intake default: donate unsold {defaultDonateUnsold ? "Yes" : "No"} —
            inherited from the seller's registration
          </div>
        </div>
      </div>
      {error && (
        <div role="alert" {...variantProps(v2, "ui2-itemform-error", ITEM_FORM.error)}>
          {error}
        </div>
      )}
      <button type="submit" disabled={loading} {...v1Only(v2, BUTTON_STYLE)} {...v2Only(v2, "ui2-btn ui2-btn--primary")}>
        {loading ? "Adding…" : "Add Item"}
      </button>
    </form>
  );
}